#include <stdbool.h>
#include <stdio.h>

struct Point { int x; int y; };

bool same_point(struct Point a, struct Point b) {
    return a.x == b.x && a.y == b.y;
}

int main(void) {
    struct Point first = {2, 3};
    struct Point second = first;
    printf("%s\n", same_point(first, second) ? "same" : "different");
    return 0;
}

#include <stdbool.h>
#include <stddef.h>

struct BufferView { const unsigned char *data; size_t length; };

bool same_bytes(struct BufferView a, struct BufferView b) {
    if (a.length != b.length) return false;
    if (a.length == 0) return true;
    if (a.data == NULL || b.data == NULL) return false;
    for (size_t i = 0; i < a.length; ++i)
        if (a.data[i] != b.data[i]) return false;
    return true;
}
